import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0006: 为什么动作结果必须经过独立验证","description":"","frontmatter":{},"headers":[],"relativePath":"zh/adr/ADR-0006-why-independent-verification.md","filePath":"zh/adr/ADR-0006-why-independent-verification.md","lastUpdated":0}`),a={name:`zh/adr/ADR-0006-why-independent-verification.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0006-为什么动作结果必须经过独立验证" tabindex="-1">ADR-0006: 为什么动作结果必须经过独立验证 <a class="header-anchor" href="#adr-0006-为什么动作结果必须经过独立验证" aria-label="Permalink to “ADR-0006: 为什么动作结果必须经过独立验证”">​</a></h1><ul><li>状态：已接受</li><li>日期：2026-10-31</li><li>关联：docs/guide/recovery-engine.md §6，probe-diagnosis.md §5</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>恢复动作最方便的&quot;成功&quot;信号是退出码 0——但它只说明命令跑完了：进程可能起了又立刻死， 服务可能起了但不监听，配置可能改了但没生效。信任退出码会把&quot;假成功&quot;写回系统， 掩盖真实故障并触发冷却，直到下次探测才被动发现。</p><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to “决策”">​</a></h2><p>每个恢复计划的验证字段（默认 <code>status_is = &quot;healthy&quot;</code>）以<strong>资源健康探针</strong>复检判定： 动作执行后转入 Verifying，探针达条件才 Recovered；验证失败则重诊断（故障可能已变化）， 进入下一计划/下一尝试。P0 验收明文：命令成功但资源仍异常时不得报告恢复成功。</p><h2 id="替代方案" tabindex="-1">替代方案 <a class="header-anchor" href="#替代方案" aria-label="Permalink to “替代方案”">​</a></h2><ul><li><strong>信任退出码</strong>：假成功（见背景）。</li><li><strong>信任动作自身的自检输出</strong>：动作与验证同源，无法发现动作实现本身的错误。</li></ul><h2 id="优缺点" tabindex="-1">优缺点 <a class="header-anchor" href="#优缺点" aria-label="Permalink to “优缺点”">​</a></h2><p>优点：恢复成功 = 可观测的健康，不是命令的回声；验证失败自然衔接重诊断。 缺点：验证要等下一个探针周期（可配置收敛）；探针质量成为恢复正确性的下限。</p><h2 id="后续影响" tabindex="-1">后续影响 <a class="header-anchor" href="#后续影响" aria-label="Permalink to “后续影响”">​</a></h2><ul><li>VerificationResult 持久化，审计可追溯&quot;为什么判定恢复&quot;。</li><li>引擎事件 <code>recovery.verification</code> 与通知事件 <code>recovery.succeeded</code> 都建立在验证通过之上。</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};